"""Helpers for selecting the latest dotted numeric release version."""


def _version_key(version):
    """Return a comparable key for a dotted numeric version string."""
    return tuple(int(part) for part in version.split("."))


def latest_version(versions):
    """Return the highest version from an iterable of dotted version strings."""
    iterator = iter(versions)
    try:
        best = next(iterator)
    except StopIteration as exc:
        raise ValueError("versions cannot be empty") from exc

    best_key = _version_key(best)
    for version in iterator:
        key = _version_key(version)
        if key > best_key:
            best = version
            best_key = key

    return best
